<script setup lang="ts">
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import LoginForm from '../components/LoginForm.vue'
import RegisterForm from '../components/RegisterForm.vue'
import { authApi, ApiError } from '../services/api'

const tab = ref('login'); const recoveryDialog = ref(false); const router = useRouter()
const recoveryEmail = ref(''); const recoveryToken = ref(''); const recoveryPassword = ref('')
const recoveryMessage = ref(''); const recoveryError = ref(''); const tokenIssued = ref(false); const recoveryLoading = ref(false)
async function requestReset() { recoveryError.value=''; recoveryMessage.value=''; recoveryLoading.value=true; try { const response=await authApi.requestPasswordReset(recoveryEmail.value); recoveryMessage.value=response.message; if(response.development_token){ recoveryToken.value=response.development_token; tokenIssued.value=true } } catch(e) { recoveryError.value=e instanceof ApiError?e.message:'No fue posible solicitar la recuperación.' } finally { recoveryLoading.value=false } }
async function confirmReset() { recoveryError.value=''; recoveryMessage.value=''; recoveryLoading.value=true; try { const response=await authApi.confirmPasswordReset(recoveryToken.value,recoveryPassword.value); recoveryMessage.value=response.message; tokenIssued.value=false } catch(e) { recoveryError.value=e instanceof ApiError?e.message:'No fue posible actualizar la contraseña.' } finally { recoveryLoading.value=false } }
</script>
<template><v-app><v-main class="auth-bg"><v-container class="fill-height"><v-row justify="center" align="center"><v-col cols="12" sm="9" md="6" lg="5"><v-card elevation="8" rounded="xl"><v-card-item class="text-center pt-8"><v-icon color="secondary" size="48">mdi-car-wrench</v-icon><v-card-title class="text-h4">Taller Mecánico</v-card-title><v-card-subtitle>Seguimiento claro para cada reparación</v-card-subtitle></v-card-item><v-card-text class="px-6 pb-8"><v-tabs v-model="tab" color="primary" grow><v-tab value="login">Acceder</v-tab><v-tab value="register">Crear cuenta</v-tab></v-tabs><v-window v-model="tab" class="mt-6"><v-window-item value="login"><LoginForm @success="router.push('/panel')" @forgot="recoveryDialog=true"/></v-window-item><v-window-item value="register"><RegisterForm @registered="tab='login'"/></v-window-item></v-window><v-divider class="my-5"/><v-btn to="/clientes" variant="outlined" color="primary" block prepend-icon="mdi-account-group">Sección de clientes</v-btn></v-card-text></v-card></v-col></v-row></v-container></v-main><v-dialog v-model="recoveryDialog" max-width="500"><v-card rounded="lg"><v-card-title>Recuperar contraseña</v-card-title><v-card-text><v-alert v-if="recoveryError" type="error" class="mb-3">{{recoveryError}}</v-alert><v-alert v-if="recoveryMessage" type="success" class="mb-3">{{recoveryMessage}}</v-alert><v-text-field v-model="recoveryEmail" label="Correo registrado" type="email"/><v-btn color="primary" block :loading="recoveryLoading" @click="requestReset">Solicitar código</v-btn><template v-if="tokenIssued"><v-divider class="my-5"/><p class="text-body-2 mb-3">Ingresa el código generado y tu nueva contraseña.</p><v-text-field v-model="recoveryToken" label="Código de recuperación"/><v-text-field v-model="recoveryPassword" label="Nueva contraseña" type="password" hint="Mínimo 10 caracteres, mayúscula, minúscula y número"/><v-btn color="primary" block :loading="recoveryLoading" @click="confirmReset">Actualizar contraseña</v-btn></template></v-card-text><v-card-actions><v-spacer/><v-btn @click="recoveryDialog=false">Cerrar</v-btn></v-card-actions></v-card></v-dialog></v-app></template>
<style scoped>.auth-bg{min-height:100vh;background:linear-gradient(135deg,#174A5E,#3E8E7E)}</style>
